import { css, cx } from "@styled-system/css"
import type { ComponentPropsWithoutRef, ReactNode } from "react"
import { forwardRef } from "react"

import { recipe, TextFieldVariantProps } from "./recipe"

const getHelperText = (id: string) => `${id}-helper-text`

type TextFieldProps = Omit<
  ComponentPropsWithoutRef<"input">,
  "size" | "width"
> & {
  leadingAddon?: ReactNode
  trailingAddon?: ReactNode
  label?: string
  helperText?: string
  required?: boolean
  id: string
} & TextFieldVariantProps

export const TextField = forwardRef<HTMLInputElement, TextFieldProps>(
  (props, ref) => {
    const [variantProps, componentProps] = recipe.splitVariantProps(props)

    const {
      className,
      leadingAddon,
      trailingAddon,
      label,
      helperText,
      id,
      required = false,
      ...rest
    } = componentProps

    const styles = recipe.raw(variantProps)
    return (
      <div className={css(styles.root)}>
        {label && (
          <div className={css(styles.heading)}>
            <label className={required ? "required" : ""} htmlFor={id}>
              {label}
            </label>
          </div>
        )}

        <div className={css(styles.container)}>
          {leadingAddon && <div>{leadingAddon}</div>}

          <input
            ref={ref}
            className={cx(css(styles.input), className)}
            required={required}
            id={id}
            aria-describedby={getHelperText(id)}
            aria-invalid={variantProps.status === "negative" ? true : false}
            {...rest}
          />

          {trailingAddon && (
            <div className={css(styles.trailingButton)}>{trailingAddon}</div>
          )}
        </div>

        {helperText && (
          <div
            className={css(styles.helper)}
            id={getHelperText(id)}
            aria-live="polite"
          >
            {helperText}
          </div>
        )}
      </div>
    )
  },
)

TextField.displayName = "TextField"

import { RecipeVariantProps, sva } from "@styled-system/css"

export const recipe = sva({
  slots: ["root", "heading", "container", "input", "trailingButton", "helper"],
  base: {
    root: {
      display: "flex",
      flexDirection: "column",
      gap: "1.5",
      width: "full",
    },
    heading: {
      textStyle: "label1",
      "&::after": {
        color: "destructive",
        content: "'*'",
        fontSize: "sm",
        marginLeft: "0.5",
      },
    },
    container: {
      alignItems: "center",
      border: "input",
      borderRadius: "md",
      shadow: "sm",
      display: "flex",
      gap: "1.5",
      minHeight: "12",
      padding: "3",
      width: "full",
      transition: "colors",
      transitionTimingFunction: "in",
      transitionDuration: "fast",
      _disabled: {
        cursor: "not-allowed",
      },
      _focusWithin: {
        borderColor: "primary",
      },
    },
    input: {
      border: "none",
      outline: "none",
      flex: "1",
      _disabled: {
        cursor: "not-allowed",
      },
    },
    trailingButton: {
      display: "flex",
      alignItems: "center",
      whiteSpace: "nowrap",
      maxHeight: "2",
    },
    helper: {
      alignSelf: "stretch",
      color: "foreground.muted",
      textStyle: "caption2",
    },
  },
  variants: {
    status: {
      normal: {},
      negative: {
        container: {
          borderColor: "destructive",
          _focusWithin: {
            borderColor: "destructive",
          },
        },
        helper: {
          color: "destructive",
        },
      },
    },
  },
  defaultVariants: {
    status: "normal",
  },
})

export type TextFieldVariantProps = RecipeVariantProps<typeof recipe>

import { cn } from "@utils/cn"
import type { ComponentPropsWithoutRef, ReactNode } from "react"
import { forwardRef } from "react"
import { type VariantProps } from "tailwind-variants"

import { textField } from "./styles"

const getHelperText = (id: string) => `${id}-helper-text`

export type TextFieldVariantProps = VariantProps<typeof textField>

type TextFieldProps = Omit<
  ComponentPropsWithoutRef<"input">,
  "size" | "width"
> & {
  leadingAddon?: ReactNode
  trailingAddon?: ReactNode
  label?: string
  helperText?: string
  required?: boolean
  id: string
} & TextFieldVariantProps

export const TextField = forwardRef<HTMLInputElement, TextFieldProps>(
  (props, ref) => {
    const {
      className,
      leadingAddon,
      trailingAddon,
      label,
      helperText,
      id,
      required = false,
      status,
      ...rest
    } = props

    const styles = textField({ status })

    return (
      <div className={styles.root()}>
        {label && (
          <div className={styles.heading()}>
            <label
              className={cn(
                required &&
                  "after:ml-0.5 after:text-sm after:text-destructive after:content-['*']",
              )}
              htmlFor={id}
            >
              {label}
            </label>
          </div>
        )}

        <div className={styles.container()}>
          {leadingAddon && <div>{leadingAddon}</div>}

          <input
            ref={ref}
            className={cn(styles.input(), className)}
            required={required}
            id={id}
            aria-describedby={getHelperText(id)}
            aria-invalid={status === "negative" ? true : false}
            {...rest}
          />

          {trailingAddon && (
            <div className={styles.trailingButton()}>{trailingAddon}</div>
          )}
        </div>

        {helperText && (
          <div
            className={styles.helper()}
            id={getHelperText(id)}
            aria-live="polite"
          >
            {helperText}
          </div>
        )}
      </div>
    )
  },
)

TextField.displayName = "TextField"

import { tv } from "tailwind-variants"

export const textField = tv({
  slots: {
    root: "flex w-full flex-col gap-1.5",
    heading: "typo-label1",
    container:
      "flex min-h-12 w-full items-center gap-1.5 rounded-md border border-stroke-subtle p-3 shadow-sm transition-colors duration-150 ease-in focus-within:border-primary [&:has(input:disabled)]:cursor-not-allowed",
    input:
      "flex-1 border-0 bg-transparent outline-none disabled:cursor-not-allowed",
    trailingButton: "flex max-h-2 items-center whitespace-nowrap",
    helper: "self-stretch text-foreground-muted typo-caption2",
  },
  variants: {
    status: {
      normal: {},
      negative: {
        container: "border-destructive focus-within:border-destructive",
        helper: "text-destructive",
      },
    },
  },
  defaultVariants: {
    status: "normal",
  },
})
